namespace OpenTPW;

/// <summary>
/// The guest walk's approximation register (docs/GUESTS.md, "Walking"; docs/reverse/WALK-plan.md §11, §13). Each entry is
/// tagged <c>[APPROX:WALK-NNN]</c> at its code site. The speed model is traced from the Mac binary; a guest's walk on the park's
/// cells is tp.exe's (GuestNavigation.Navigate: the route search 0x511420, the edge test 0x4d8750 and commit 0x510510, avoid_walls
/// 0x50e4a0 with its corner blocks, follow_path 0x50ed10 with the block stamps, the progress 0x50fd40 and the steering step 0x50f3b0
/// with its own arithmetic), checked against the original in the x86 oracle; separation is the Mac's (BIN labels at the code sites).
/// Retired: WALK-002 (avoid_walls' corner blocks and the position's cell) and WALK-009 (the progress measure and its resets).
/// </summary>
public static class WalkApproximations
{
	public static readonly IReadOnlyList<(string Id, string Rule)> Entries = new[]
	{
		("WALK-001", "the amount of the special ingredient stays at the ride build's 50 (tp.exe 0x4db090 stores 0x32 at +0x198, 0x4db3b3), so a Sugar visit adds 3 (0x4fe5f8: trunc(6 x amount / 100)); the original's shop window shows a 0..100 amount slider for ingredient shops only (range set at 0x4b06d2; refresh 0x4b0950 hides controls 0xc086/0xc084 unless the type's ingredient is 1..4), writes it to the object (0x4b0aa0) or to every object of that type (0x4b0ae0) and saves it as mAmountOfSpecialIngredient (0x4db7d0); OpenTPW has no slider, its save does not store the amount and the original-save import skips it"),
		("WALK-003", "separation's neighbours are the guests outside rides and shops (not Using, HeldByGuard or Gone) in OpenTPW's cell lists, rebuilt every park turn in guest order with movers appended; the original (tp.exe query 0x5102f0, Mac 0x10087c) walks per-cell thing lists that are head-inserted when a thing enters a cell (0x50b6a0 via 0x4d91f0) and never rebuilt, keeps class-1 guests whatever their state, and also keeps staff (classes 4-8) and the online avatar (class 18); the neighbour position (thing +4/+6 = navigation position >> 8, written by 0x4fa2a0) matches OpenTPW's"),
		("WALK-004", "the walks to a ride (state 10) and out of the park (state 18) set a destination one path cell at a time (Grid.TryStep over the cell links, each a fresh search from the guest's cell), where tp.exe's states set one destination for the whole walk (state 10 0x4ffbc0 through 0x4fa5f0, the leaving gate's crossing cell 0x4d86d0) and its search (0x511420) string-pulls the route; the search, the set-up 0x50f8e0, the refill by a new search (0x50efce) and both reroutes are ported (WalkSearch, GuestNavigation.Navigate)"),
		("WALK-005", "the edge test 0x4d8750 reads only the cell map: OpenTPW's cells hold no object or thing references, so an object standing on a target cell (0x5363f0, its type record's 0x53ad20 bits) never blocks, a type-9 target's ride thing (on its owner cell +0x10, type 3: 0x42a440, 0x4dd4e0 +0x118) never decides a mask-2 step, and the underground link byte +0x22 (0x522770 with 0x81b4cc) is not kept; the types are the ones OpenTPW's tools write (path, queue and track cells; map init 0x536490's types 2, 5, 7 and 0x1e are not written, WALK-008)"),
		("WALK-006", "queue walks (states 12 and 13), the arrival lanes' walks (WALK-008) and walks restored from saves made before the original walk keep OpenTPW's route walk: the route's cells (and a queue walk's next queue cells ahead and behind) are the walkable ones, avoid_walls has its edge branch only (with the probe's cell), refills come from the stored route, the stuck reroute prepends the current cell to the rest, progress compares raw remaining distances in the five-waypoint window, and the Mac's rounding FixMul/FixDiv apply; in the original every walk is the search and edge-test walk of Navigate, a step from a queue cell being open (edge test 0x4d8750) into a path, queue or queue-end neighbour whose +0x0C link points back, or into a 0x1e walkway unless the mask is 2"),
		("WALK-007", "a route walk (WALK-006) restored from a save made before the original walk ends without a replan when a grid edit takes a cell or link of its route, and the queue recompute's own stamp of its back cell (tp.exe 0x4de1f0, after one of its queue cells became path) is not made; the block stamps of every cell type change (0x4d8c60 from 0x5346d0, 0x5348d0, 0x538fc0) and the walk's comparison (0x50ed6c, a search in mode 1) are ported"),
		("WALK-008", "guests on the arrival lanes walk off the path grid, with no wall force and every position committed; the original walks them like every guest (route search 0x50f8e0, commit 0x510510 and edge test 0x4d8750 with the walk mask), the lane cells being type 0x1e or path from map init 0x536490, so only map-edge, entrance-building, water, ride and queue cells could push or refuse them; OpenTPW's cell map does not type the lane cells (map init 0x536490 gives the cells outside the park type 7, or 0x1e and 2 by their MAP attributes 0x80 and 2)"),
		("WALK-010", "the needs phase that gates the toilet speed term compares the park turn with OpenTPW's guest id; the original compares the low two bits of the tick with the thing id (tp.exe 0x501676), taken from one pool of 10239 slots shared by every thing kind (allocator 0x516270, ids 1, 2, 3, ... on a fresh park, freed ids reused last-in first-out after the turn's deferred destroy), so the phase depends on the whole construction and destroy history")
	};
}
